// OpenWeather condition id (+ night) → Meteo icon id.
// Night moon set is only 37 (clear), 38 (few clouds), 39 (partly cloudy).
// 36/40–42 are windsock / thermometers — never use those as sky icons.
// Rain/storm/snow at night use the shared cloud glyphs (no moon variants).
inline int fromOpenWeather(int weatherId, bool night) {
  if (weatherId <= 0) return night ? 37 : 1;
  if (weatherId >= 200 && weatherId < 300) {
    if (weatherId < 210) return 9;   // thunderstorm
    if (weatherId < 230) return 10;
    return 16;                       // heavy / severe
  }
  if (weatherId >= 300 && weatherId < 400) {
    // Drizzle: day can show sun+rain (4); night → rain cloud (14).
    return night ? 14 : 4;
  }
  if (weatherId >= 500 && weatherId < 600) {
    if (weatherId < 502) return night ? 14 : 4;   // light rain
    if (weatherId < 520) return 15;               // heavy rain
    return 9;                                     // shower rain
  }
  if (weatherId >= 600 && weatherId < 700) {
    if (weatherId < 602) return 25;
    if (weatherId < 620) return 26;
    return 27;
  }
  if (weatherId >= 700 && weatherId < 800) {
    if (weatherId == 781) return 22;
    return night ? 21 : 6;  // fog: wavy lines, or hazy sun by day
  }
  if (weatherId == 800) return night ? 37 : 1;
  if (weatherId == 801) return night ? 38 : 2;
  if (weatherId == 802) return night ? 39 : 3;
  if (weatherId == 803) return night ? 39 : 8;
  if (weatherId == 804) return 13;  // overcast — same day/night cloud
  return night ? 39 : 7;
}

// Prefer OpenWeather icon code ("01d"/"10n") so day/night matches the forecast hour.
inline int fromOpenWeatherIcon(const char* code, int weatherIdFallback) {
  bool night = false;
  if (code && code[0] && code[1] && (code[2] == 'd' || code[2] == 'n')) {
    night = (code[2] == 'n');
    int n = (code[0] - '0') * 10 + (code[1] - '0');
    switch (n) {
      case 1: return night ? 37 : 1;   // clear
      case 2: return night ? 38 : 2;   // few clouds
      case 3: return night ? 39 : 3;   // scattered
      case 4: return night ? 39 : 13;  // broken / overcast → night uses cloudiest moon
      case 9: return 15;              // shower rain
      case 10: return night ? 14 : 4; // rain
      case 11: return 10;             // thunderstorm
      case 13: return 25;             // snow
      case 50: return night ? 21 : 6; // mist
      default: break;
    }
  }
  return fromOpenWeather(weatherIdFallback, night);
}

